-- Dumping structure for function enablink.get_json_jadwal_volunteer_day
DELIMITER //
CREATE FUNCTION `get_json_jadwal_volunteer_day`(`semester_id` INT, `student_id` INT, `day_int` INTEGER(1)) RETURNS longtext CHARSET latin1
BEGIN
	set @result_data := '';
	SELECT
		IFNULL(CONCAT( '[', GROUP_CONCAT( concat( '["', `app_schedule_volunteer`.`start_at`, '","', `app_schedule_volunteer`.`end_at`, '"]' ) ), ']' ),'[]') INTO @result_data 
	FROM
		app_schedule_volunteer 
	WHERE
		app_schedule_volunteer.student_id = student_id 
		AND app_schedule_volunteer.semester_id = semester_id 
		AND app_schedule_volunteer.DAY = day_int;
	RETURN(@result_data);
END//
DELIMITER ;

